import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { CalendarRange } from 'lucide-react';
import avgFareByMonth from '@/data/avg_fare_by_month.json';
import type { AvgFareByMonth } from '@/types/charts';
import { axisTick, formatFareTick, tooltipStyle } from './chartTheme';

/**
 * Average fare by month — train.ipynb cell 7 (`df.groupby('month').fare_amount.mean()`),
 * generated by scripts/generate_chart_data.py. Answers "which months are fares the highest".
 */
export function AvgFareByMonthChart() {
  const data = avgFareByMonth as AvgFareByMonth[];
  const maxFare = Math.max(...data.map((d) => d.avgFare));

  return (
    <Card className="rounded-lg border">
      <CardHeader className="flex-row items-center gap-2 space-y-0 pb-3">
        <CalendarRange className="h-5 w-5 text-muted-foreground" />
        <div>
          <CardTitle className="text-lg font-semibold">Average Fare by Month</CardTitle>
          <CardDescription className="text-sm">Which months are fares the highest</CardDescription>
        </div>
      </CardHeader>
      <CardContent>
        <ResponsiveContainer width="100%" height={240}>
          <BarChart data={data} margin={{ top: 10, right: 10, left: 10, bottom: 0 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" vertical={false} />
            <XAxis dataKey="month" tick={axisTick} axisLine={false} tickLine={false} />
            <YAxis
              tick={axisTick}
              axisLine={false}
              tickLine={false}
              tickFormatter={formatFareTick}
            />
            <Tooltip
              cursor={{ fill: 'var(--accent)' }}
              contentStyle={tooltipStyle}
              formatter={(value) =>
                [`$${Number(value ?? 0).toFixed(2)}`, 'Average fare'] as [string, string]
              }
            />
            <Bar dataKey="avgFare" radius={[4, 4, 0, 0]} maxBarSize={40}>
              {data.map((entry) => (
                <Cell
                  key={entry.month}
                  fill={entry.avgFare === maxFare ? 'var(--chart-2)' : 'var(--chart-1)'}
                />
              ))}
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </CardContent>
    </Card>
  );
}
